function addedLetter(s: string, t: string): string {
  let acc = 0;
  for (let i = 0; i < s.length; i++) acc ^= s.charCodeAt(i);
  for (let i = 0; i < t.length; i++) acc ^= t.charCodeAt(i);
  return String.fromCharCode(acc);
}

